}

_choice_display_id() {
    _argc_util_cache 60 _helper_scrcpy_display_ids scrcpy-display-ids
}

_choice_serial() {
    command -v adb >/dev/null 2>&1 || return 0
    adb devices 2>/dev/null | gawk '$2 == "device" { print $1 }'
}

_choice_start_app() {
    _argc_util_cache 300 _helper_scrcpy_apps scrcpy-apps
}

_choice_video_encoder() {
    _argc_util_cache 60 _helper_scrcpy_video_encoders scrcpy-video-encoders
}

_helper_scrcpy_apps() {
    scrcpy --list-apps 2>&1 | gawk '
        /^[[:space:]]/ {
            v = $NF
            if (v ~ /^[A-Za-z0-9_]+([.][A-Za-z0-9_]+)+$/) print v
        }
    '
}

_helper_scrcpy_audio_encoders() {
    _helper_scrcpy_list --list-encoders '--audio-encoder='
}

_helper_scrcpy_camera_ids() {
    _helper_scrcpy_list --list-cameras '--camera-id='
}

_helper_scrcpy_camera_sizes() {
    scrcpy --list-camera-sizes 2>&1 | gawk '
        /^[[:space:]]*- [[:digit:]]+x[[:digit:]]+/ {
            v = $2
            sub(/[[:space:]]*\(.*$/, "", v)
            print v
        }
    '
}

_helper_scrcpy_display_ids() {
    _helper_scrcpy_list --list-displays '--display-id='
}

_helper_scrcpy_list() {
    local flag="$1" marker="$2" v
    scrcpy "$flag" 2>&1 | gawk -v m="$marker" '
        index($0, m) {
            v = substr($0, index($0, m) + length(m))
            sub(/[ \t].*$/, "", v)
            if (v != "") print v
        }
    '
}

_helper_scrcpy_video_encoders() {
    _helper_scrcpy_list --list-encoders '--video-encoder='
}
